function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // boy
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 20);
  ctx.lineTo(W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 30);
  ctx.lineTo(W/4 - 20, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 30);
  ctx.lineTo(W/4 + 20, H/2 + 40);
  ctx.stroke();

  // girl
  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 20);
  ctx.lineTo(W - W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 30);
  ctx.lineTo(W - W/4 - 20, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 30);
  ctx.lineTo(W - W/4 + 20, H/2 + 40);
  ctx.stroke();

  // heart
  ctx.beginPath();
  ctx.moveTo(W/2 + 20 * Math.sin(t), H/2 - 20 * Math.cos(t));
  ctx.bezierCurveTo(W/2 + 10 * Math.sin(t), H/2 - 30 * Math.cos(t), W/2 - 10 * Math.sin(t), H/2 - 30 * Math.cos(t), W/2 - 20 * Math.sin(t), H/2 - 20 * Math.cos(t));
  ctx.bezierCurveTo(W/2 - 30 * Math.sin(t), H/2 - 10 * Math.cos(t), W/2 - 30 * Math.sin(t), H/2 + 10 * Math.cos(t), W/2 - 20 * Math.sin(t), H/2 + 20 * Math.cos(t));
  ctx.bezierCurveTo(W/2 - 10 * Math.sin(t), H/2 + 30 * Math.cos(t), W/2 + 10 * Math.sin(t), H/2 + 30 * Math.cos(t), W/2 + 20 * Math.sin(t), H/2 + 20 * Math.cos(t));
  ctx.bezierCurveTo(W/2 + 30 * Math.sin(t), H/2 + 10 * Math.cos(t), W/2 + 30 * Math.sin(t), H/2 - 10 * Math.cos(t), W/2 + 20 * Math.sin(t), H/2 - 20 * Math.cos(t));
  ctx.stroke();

  ctx.restore();
}
